646	-- A sheet's settings that carry a figure, each recorded from a date: the floor, the late percent, the
647	-- terms (the sheet's, and each grade's as terms-<grade>), the clerk limit and the cap. The value in
648	-- force on a date is the one with the latest from-date on or before it; before every from-date it is
649	-- the sheet's starting value (floor 1.00, late percent 0.00, terms 14; none for the others). A null
650	-- value records "none" from that date: no clerk limit, no cap, or a grade using the sheet's terms.
651	CREATE TABLE sheet_setting (
652	    id            BIGINT AUTO_INCREMENT PRIMARY KEY,
653	    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
654	    setting_key   VARCHAR(20)  NOT NULL,
655	    from_date     DATE         NOT NULL,
656	    setting_value VARCHAR(20)
657	);
658	CREATE UNIQUE INDEX sheet_setting_sheet_key_from ON sheet_setting (sheet_id, setting_key, from_date);
659	
660	-- The values already kept are in force from the beginning of time.
661	INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
662	    SELECT id, 'floor', DATE '0001-01-01', CAST(due_floor AS VARCHAR) FROM sheet WHERE due_floor <> 1.00;
663	INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
664	    SELECT id, 'late-pct', DATE '0001-01-01', CAST(late_pct AS VARCHAR) FROM sheet WHERE late_pct <> 0.00;
665	INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
666	    SELECT id, 'terms', DATE '0001-01-01', CAST(terms AS VARCHAR) FROM sheet WHERE terms <> 14;
667	INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
668	    SELECT id, 'clerk-limit', DATE '0001-01-01', CAST(clerk_limit AS VARCHAR) FROM sheet WHERE clerk_limit IS NOT NULL;
669	INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
670	    SELECT id, 'cap', DATE '0001-01-01', CAST(due_cap AS VARCHAR) FROM sheet WHERE due_cap IS NOT NULL;
671	INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
672	    SELECT sheet_id, 'terms-' || grade, DATE '0001-01-01', CAST(terms AS VARCHAR) FROM sheet_grade_terms;
673	
674	DROP TABLE sheet_grade_terms;
675	ALTER TABLE sheet DROP COLUMN due_floor;
676	ALTER TABLE sheet DROP COLUMN late_pct;
677	ALTER TABLE sheet DROP COLUMN terms;
678	ALTER TABLE sheet DROP COLUMN clerk_limit;
679	ALTER TABLE sheet DROP COLUMN due_cap;
