61	        if (of.isEmpty()) return Map.of();
62	        return logs.findByClaimIdInOrderByIdAsc(of.stream().map(Claim::getId).toList()).stream()
63	                .collect(Collectors.groupingBy(ClaimLog::getClaimId));
