74	        refuseBadCorrection(sheetId, personId, amount, corrects);
75	        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note), corrects);
76	        claim.setDueBy(dated.plusDays(settings.termsFor(sheetId, person.gradeOn(dated), dated)));
77	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
78	        claim = claims.saveAndFlush(claim);
79	        log(user, person, claim);
80	        record("CLAIM_ADDED", user, person, claim, claim.getNumber());
81	        rollup.recordSince(sheetId, user, before);
82	        return claim;
83	    }
84	
85	    @Transactional
86	    public Claim update(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
87	            String corrects) {
88	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
89	        LocalDate dated = date != null ? date : sheets.today(sheetId);
90	        refuseClosed(sheetId, claim.getDate());
91	        refuseClosed(sheetId, dated);
92	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
93	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
94	                .orElseThrow(PersonNotFoundException::new);
95	        person.requireClaimable(dated);
96	        refuseBadCorrection(sheetId, person.getId(), amount, corrects);
97	        RollupService.Snapshot before = rollup.snapshot(sheetId);
98	        claim.setAmount(amount);
99	        claim.setCorrects(corrects);
100	        claim.setDate(dated);
101	        claim.setNote(noteOf(note));
102	        claims.flush();
103	        record("CLAIM_EDITED", user, person, claim, claim.getNumber());
104	        rollup.recordSince(sheetId, user, before);
105	        return claim;
106	    }
107	
108	    /** Move the claim to {@code next}; refused when its current status does not allow it (a PENDING
109	     * claim can only be voided here: it is approved or rejected instead). Settling it fixes what is due
110	     * on it then (the figure it is bound to, when a statement bound it, otherwise its person's rate then)
111	     * together with its late charge then (none on a correction); the user who opened it cannot settle it,
112	     * and a clerk's settle of it when that due is above the sheet's clerk limit (a due that is n/a is
113	     * within any limit) leaves it PENDING instead, fixing nothing, until a steward approves or rejects
114	     * it. A claim deferred on the sheet's today cannot be settled. A voided claim keeps its number, if it had one. */
115	    @Transactional
116	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next) {
117	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
118	        refuseClosed(sheetId, claim.getDate());
119	        if (!claim.getStatus().canBecome(next) || (claim.getStatus() == ClaimStatus.PENDING && next != ClaimStatus.VOID)) {
120	            throw new ClaimStatusChangeException();
121	        }
122	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimStatusChangeException();
123	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) throw new ClaimSelfSettleException();
124	        RollupService.Snapshot before = rollup.snapshot(sheetId);
125	        String number = claim.getNumber();
126	        if (next == ClaimStatus.OPEN) {
127	            number = nextNumber(sheetId, claim.getDate());
128	            claim.setOpenedBy(user);
129	        }
130	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
131	                .orElseThrow(PersonNotFoundException::new);
132	        if (next == ClaimStatus.SETTLED) {
133	            BigDecimal figure = claim.isStated() ? claim.getStatedDue() : rollup.dueOf(claim, person);
134	            BigDecimal due = figure == null ? null : figure.add(rollup.lateChargeOf(claim, figure));
135	            if (overLimit(sheetId, user, due)) next = ClaimStatus.PENDING;
136	            else claim.setSettledDue(due);
137	        }
138	        claim.setStatus(next);
139	        claim.setNumber(number);
140	        claims.flush();
141	        log(user, person, claim);
142	        String event = switch (next) {
143	            case OPEN -> "CLAIM_OPENED";
144	            case PENDING -> "CLAIM_PENDING";
145	            case SETTLED -> "CLAIM_SETTLED";
146	            case VOID -> "CLAIM_VOIDED";
147	            case DRAFT -> throw new IllegalStateException();
148	        };
149	        if (next == ClaimStatus.SETTLED) {
150	            record(event, user, person, claim, number, "due=" + dueText(claim.getSettledDue()));
151	        } else {
152	            record(event, user, person, claim, number);
153	        }
154	        rollup.recordSince(sheetId, user, before);
155	        return claim;
156	    }
157	
158	    /** Defer an OPEN claim until {@code until}, a date after the sheet's today: until the sheet's today
159	     * reaches it the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
160	     * statement. Refused unless the claim is OPEN, when {@code until} is not after the sheet's today, and
161	     * when the claim is dated in a closed period. */
162	    @Transactional
163	    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
164	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
165	        refuseClosed(sheetId, claim.getDate());
166	        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusChangeException();
167	        if (!until.isAfter(sheets.today(sheetId))) throw new ClaimDeferException();
168	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
169	                .orElseThrow(PersonNotFoundException::new);
170	        RollupService.Snapshot before = rollup.snapshot(sheetId);
171	        claim.setDeferredUntil(until);
172	        claims.flush();
173	        record("CLAIM_DEFERRED", user, person, claim, claim.getNumber(), "until=" + until);
174	        rollup.recordSince(sheetId, user, before);
175	        return claim;
176	    }
177	
178	    /** A steward's approval of a PENDING claim: it becomes SETTLED, fixing what is due on it then (its
179	     * live figure, which no statement binds while it is PENDING, together with its late charge then).
180	     * Refused unless the claim is PENDING, and when the user is not a steward or opened the claim. */
181	    @Transactional
182	    public Claim approve(String sheetId, String user, long claimId) {
183	        Claim claim = lockPending(sheetId, user, claimId);
184	        if (user.equals(claim.getOpenedBy())) throw new ClaimNotStewardException();
185	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
186	                .orElseThrow(PersonNotFoundException::new);
187	        RollupService.Snapshot before = rollup.snapshot(sheetId);
188	        BigDecimal figure = rollup.dueOf(claim, person);
189	        BigDecimal due = figure == null ? null : figure.add(rollup.lateChargeOf(claim, figure));
190	        claim.setSettledDue(due);
191	        claim.setStatus(ClaimStatus.SETTLED);
192	        claims.flush();
193	        log(user, person, claim);
194	        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), "due=" + dueText(due));
195	        rollup.recordSince(sheetId, user, before);
196	        return claim;
197	    }
198	
199	    /** A steward's rejection of a PENDING claim, for {@code reason}: it goes back to OPEN, bound again
200	     * by its person's last statement if that statement included it. Refused unless the claim is
201	     * PENDING, and when the user is not a steward. */
202	    @Transactional
203	    public Claim reject(String sheetId, String user, long claimId, String reason) {
204	        Claim claim = lockPending(sheetId, user, claimId);
205	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
206	                .orElseThrow(PersonNotFoundException::new);
207	        RollupService.Snapshot before = rollup.snapshot(sheetId);
208	        claim.setStatus(ClaimStatus.OPEN);
209	        claims.flush();
210	        log(user, person, claim);
211	        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), "reason=" + reason);
212	        rollup.recordSince(sheetId, user, before);
213	        return claim;
214	    }
215	
216	    /** A steward's move of a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
217	     * number and date, loses any figure a statement bound it to (it is live again until its new
218	     * person's next statement), and is listed as its new person's newest claim. Refused when the user
219	     * is not a steward, when the claim is SETTLED or VOID, is a correction (it corrects a claim of its
220	     * own person) or already belongs to the person, when it is dated in a closed period, and when it
221	     * is dated after the new person's retirement date. */
222	    @Transactional
223	    public Claim reassign(String sheetId, String user, long claimId, long personId) {
224	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
225	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
226	        refuseClosed(sheetId, claim.getDate());
227	        ClaimStatus status = claim.getStatus();
228	        if ((status != ClaimStatus.DRAFT && status != ClaimStatus.OPEN && status != ClaimStatus.PENDING)
229	                || claim.isCorrection() || claim.getPersonId() == personId) {
230	            throw new ClaimReassignException();
231	        }
232	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
233	                .orElseThrow(PersonNotFoundException::new);
234	        Person to = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
235	        to.requireClaimable(claim.getDate());
236	        RollupService.Snapshot before = rollup.snapshot(sheetId);
237	        claim.setPersonId(to.getId());
238	        claim.unbind();
239	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
240	        claims.flush();
241	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(), "from=" + from.getName(), "to=" + to.getName());
242	        rollup.recordSince(sheetId, user, before);
243	        return claim;
244	    }
245	
246	    /** A steward's re-settle of a SETTLED claim: it is fixed again at what would be due on it now were
247	     * it OPEN and bound by no statement (its person's rate and grade, the sheet's floor and its late
248	     * charge, all as they are now). Refused unless the claim is SETTLED, when the user is not a
249	     * steward, and when it is dated in a closed period. */
250	    @Transactional
251	    public Claim resettle(String sheetId, String user, long claimId) {
252	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
253	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
254	        refuseClosed(sheetId, claim.getDate());
255	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusChangeException();
256	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
257	                .orElseThrow(PersonNotFoundException::new);
258	        RollupService.Snapshot before = rollup.snapshot(sheetId);
259	        BigDecimal old = claim.getSettledDue();
260	        BigDecimal due = rollup.openShownOf(claim, person);
261	        claim.setSettledDue(due);
262	        claims.flush();
263	        log(user, person, claim);
264	        record("CLAIM_RESETTLED", user, person, claim, claim.getNumber(), "old=" + dueText(old), "new=" + dueText(due));
265	        rollup.recordSince(sheetId, user, before);
266	        return claim;
267	    }
268	
269	    /** The PENDING claim, locked, for a steward to approve or reject. */
270	    private Claim lockPending(String sheetId, String user, long claimId) {
271	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
272	        refuseClosed(sheetId, claim.getDate());
273	        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusChangeException();
274	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
275	        return claim;
276	    }
