278	    private static String dueText(BigDecimal due) {
279	        return due == null ? "n/a" : due.toPlainString();
280	    }
281	
282	    /** The figure the claim shows and totals now, without its late charge; null when it has no figure
283	     * (see {@link RollupService#figureOf}). */
284	    public BigDecimal figureOf(Claim claim, Person person) {
285	        return rollup.figureOf(claim, person);
286	    }
287	
288	    /** What is due on the claim as it shows and totals now, its late charge included; null when it has
289	     * no figure (see {@link RollupService#shownOf}). */
290	    public BigDecimal shownOf(Claim claim, Person person) {
291	        return rollup.shownOf(claim, person);
292	    }
293	
294	    /** Write the status the claim has now to its log, with the sheet's today and what is due on it as
295	     * it shows now. */
296	    private void log(String user, Person person, Claim claim) {
297	        logs.save(new ClaimLog(claim.getId(), claim.getStatus(), user, sheets.today(claim.getSheetId()),
298	                rollup.shownOf(claim, person)));
299	    }
