301	    /** Record a change to the claim; {@code number}, the number it has (or had), follows when there is one,
302	     * then any {@code extra} fields. */
303	    private void record(String event, String user, Person person, Claim claim, String number, String... extra) {
304	        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
305	                "amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
306	                "date=" + claim.getDate()));
307	        if (number != null) fields.add("number=" + number);
308	        fields.addAll(List.of(extra));
309	        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
310	    }
311	
312	    /** The number a claim dated {@code date} is given when opened now: within the period containing
313	     * that date ({@code <period name>-<n>}, or {@code X-<n>} when none does) while the sheet numbers by
314	     * period, otherwise the next sheet-wide number. */
315	    private String nextNumber(String sheetId, LocalDate date) {
316	        if (!sheets.numbersByPeriod(sheetId)) return String.valueOf(sheets.nextClaimNumber(sheetId));
317	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
318	                .filter(p -> !date.isBefore(p.getFrom()) && !date.isAfter(p.getTo()))
319	                .findFirst()
320	                .map(p -> p.getName() + "-" + sheets.nextInSequence(sheetId, "period:" + p.getId()))
321	                .orElseGet(() -> "X-" + sheets.nextInSequence(sheetId, "none"));
322	    }
323	
324	    /** Whether a settle by {@code user} of a claim whose due is {@code due} needs a steward's approval:
325	     * the user is a clerk and the due is above the sheet's clerk limit. */
326	    private boolean overLimit(String sheetId, String user, BigDecimal due) {
327	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
328	        BigDecimal limit = settings.clerkLimit(sheetId);
329	        return limit != null && due.compareTo(limit) > 0;
330	    }
331	
332	    /** Refuse a correction (a negative {@code amount}) that does not name, by number, a SETTLED claim of
333	     * the person, and a claim that names one without being a correction. */
334	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
335	        if (amount.signum() >= 0) {
336	            if (corrects != null) throw new ClaimCorrectionException();
337	            return;
338	        }
339	        if (corrects == null) throw new ClaimCorrectionException();
340	        claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
341	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
342	                .orElseThrow(ClaimCorrectionException::new);
343	    }
344	
345	    /** Refuse a change that touches {@code date} when a closed period of the sheet contains it. */
346	    private void refuseClosed(String sheetId, LocalDate date) {
347	        if (periods.closedOn(sheetId, date)) throw new ClaimPeriodClosedException();
348	    }
349	
350	    private static String noteOf(String note) {
351	        return note == null ? "" : note.trim();
352	    }
