264	export class Settings {
265	  private readonly session = inject(Session);
266	  private readonly service = inject(SettingsService);
267	
268	  protected readonly roles = ROLES;
269	  /** The clerk limit in force; null when there is none. */
270	  protected readonly clerkLimit = signal<string | null>(null);
271	  /** The floor in force, with two decimals; empty until read. */
272	  protected readonly floor = signal('');
273	  /** The cap in force, with two decimals; null when there is none. */
274	  protected readonly cap = signal<string | null>(null);
275	  /** Every cap recorded, each from its date, oldest first, once one is saved. */
276	  readonly capSaved = output<Dated<string | null>[]>();
277	  protected readonly given = signal<RoleGiven[]>([]);
278	  /** The terms in force, in days, as text; empty until read. */
279	  protected readonly terms = signal('');
280	  protected readonly grades = GRADES;
281	  /** The grades' own terms in force, in days, by grade; a grade not in it uses the sheet's terms. */
282	  protected readonly gradeTerms = signal<Partial<Record<Grade, number>>>({});
283	  /** The late percent in force, with two decimals; empty until read. */
284	  protected readonly latePct = signal('');
285	  /** Every floor recorded, each from its date, oldest first, once one is saved. */
286	  readonly floorSaved = output<Dated[]>();
287	  /** Every late percent recorded, each from its date, oldest first, once one is saved. */
288	  readonly latePctSaved = output<Dated[]>();
289	  /** The policy date as set; null when it is the sheet's today. */
290	  protected readonly policyDate = signal<string | null>(null);
291	  /** The policy date saved; null when it is the sheet's today. */
292	  readonly policyDateSaved = output<string | null>();
293	
294	  /** The period numbering from date as set; null when it is off. */
295	  protected readonly periodNumberingFrom = signal<string | null>(null);
296	
297	  protected readonly limit = signal('');
298	  protected readonly floorInput = signal('');
299	  protected readonly capInput = signal('');
300	  protected readonly termsInput = signal('');
301	  protected readonly latePctInput = signal('');
302	  protected readonly gradeTermsInput = signal<Record<Grade, string>>(blankGrades());
303	  protected readonly policyDateInput = signal('');
304	  protected readonly periodNumberingFromInput = signal('');
305	  /** The date each dated setting is saved from (YYYY-MM-DD); blank for the sheet's today. */
306	  protected readonly limitFrom = signal('');
307	  protected readonly floorFrom = signal('');
308	  protected readonly capFrom = signal('');
309	  protected readonly termsFrom = signal('');
310	  protected readonly latePctFrom = signal('');
311	  protected readonly gradeTermsFrom = signal<Record<Grade, string>>(blankGrades());
312	  /** Whether each field was typed in (a key pressed in it, even one that left its value as it was)
313	   *  since the settings were last loaded or saved; a field is saved when it was, or when it differs
314	   *  from the value in force. */
315	  protected limitChanged = false;
316	  protected floorChanged = false;
317	  protected capChanged = false;
318	  protected termsChanged = false;
319	  protected latePctChanged = false;
320	  protected readonly gradeTermsChanged = new Set<Grade>();
321	  protected policyDateChanged = false;
322	  protected periodNumberingFromChanged = false;
323	  protected readonly settingsError = signal<string | null>(null);
324	  protected readonly roleUser = signal('');
325	  protected readonly role = signal('');
326	  protected readonly roleError = signal<string | null>(null);
327	  /** A submit is waiting for its answer; another submit of the same form meanwhile is ignored. */
328	  private savingSettings = false;
329	  /** A settings submit came while one was waiting; it is made once that one is answered. */
330	  private settingsResubmit = false;
331	  private savingRole = false;
332	
333	  constructor() {
334	    effect(() => {
335	      const sheet = this.session.sheetId();
336	      this.session.loads();
337	      this.clerkLimit.set(null);
338	      this.floor.set('');
339	      this.given.set([]);
340	      this.limit.set('');
341	      this.floorInput.set('');
342	      this.cap.set(null);
343	      this.capInput.set('');
344	      this.capChanged = false;
345	      this.terms.set('');
346	      this.termsInput.set('');
347	      this.limitChanged = false;
348	      this.floorChanged = false;
349	      this.termsChanged = false;
350	      this.gradeTerms.set({});
351	      this.gradeTermsInput.set(blankGrades());
352	      this.gradeTermsChanged.clear();
353	      this.latePct.set('');
354	      this.latePctInput.set('');
355	      this.latePctChanged = false;
356	      this.policyDate.set(null);
357	      this.policyDateInput.set('');
358	      this.policyDateChanged = false;
359	      this.periodNumberingFrom.set(null);
360	      this.periodNumberingFromInput.set('');
361	      this.periodNumberingFromChanged = false;
362	      this.limitFrom.set('');
363	      this.floorFrom.set('');
364	      this.capFrom.set('');
365	      this.termsFrom.set('');
366	      this.latePctFrom.set('');
367	      this.gradeTermsFrom.set(blankGrades());
368	      this.settingsError.set(null);
369	      this.roleUser.set('');
370	      this.role.set('');
371	      this.roleError.set(null);
372	      if (sheet) void this.read(sheet);
373	    });
374	    // What is in force follows the sheet's today: re-read it when the today changes.
375	    let shownToday: string | null = null;
376	    effect(() => {
377	      const today = this.session.today();
378	      const sheet = untracked(() => this.session.sheetId());
379	      if (shownToday !== null && today !== shownToday && sheet) void this.read(sheet);
380	      shownToday = today;
381	    });
382	  }
383	
384	  protected value(event: Event): string {
385	    return (event.target as HTMLInputElement).value;
386	  }
387	
388	  protected setGradeTermsFrom(grade: Grade, text: string): void {
389	    this.gradeTermsFrom.update((inputs) => ({ ...inputs, [grade]: text }));
390	  }
391	
392	  protected setGradeTermsInput(grade: Grade, text: string): void {
393	    this.gradeTermsInput.update((inputs) => ({ ...inputs, [grade]: text }));
394	  }
395	
396	  /** The grade's own terms in force, as text; empty when it uses the sheet's terms. */
397	  protected gradeTermsShown(grade: Grade): string {
398	    const own = this.gradeTerms()[grade];
399	    return own === undefined ? '' : String(own);
400	  }
401	
402	  protected async saveSettings(event: Event): Promise<void> {
403	    event.preventDefault();
404	    if (this.savingSettings) {
405	      this.settingsResubmit = true;
406	      return;
407	    }
408	    this.settingsError.set(null);
409	    const sheet = this.session.sheetId();
410	    if (!sheet) return;
411	    const limit = this.limit().trim();
412	    const floor = this.floorInput().trim();
413	    const saveLimit = this.limitChanged || limit !== (this.clerkLimit() ?? '');
414	    const saveFloor = this.floorChanged || floor !== this.floor();
415	    const cap = this.capInput().trim();
416	    const saveCap = this.capChanged || cap !== (this.cap() ?? '');
417	    const terms = this.termsInput().trim();
418	    const saveTerms = this.termsChanged || terms !== this.terms();
419	    const gradeTerms = GRADES.map((grade) => ({ grade, text: this.gradeTermsInput()[grade].trim() })).filter(
420	      ({ grade, text }) => this.gradeTermsChanged.has(grade) || text !== this.gradeTermsShown(grade),
421	    );
422	    const latePct = this.latePctInput().trim();
423	    const saveLatePct = this.latePctChanged || latePct !== this.latePct();
424	    const policyDate = this.policyDateInput().trim();
425	    const savePolicyDate = this.policyDateChanged || policyDate !== (this.policyDate() ?? '');
426	    const numberingFrom = this.periodNumberingFromInput().trim();
427	    const saveNumberingFrom =
428	      this.periodNumberingFromChanged || numberingFrom !== (this.periodNumberingFrom() ?? '');
429	    const limitFrom = this.limitFrom().trim();
430	    const floorFrom = this.floorFrom().trim();
431	    const capFrom = this.capFrom().trim();
432	    const termsFrom = this.termsFrom().trim();
433	    const latePctFrom = this.latePctFrom().trim();
434	    const gradeTermsFrom = { ...this.gradeTermsFrom() };
435	    const badFrom = [
436	      saveLimit ? limitFrom : '',
437	      saveFloor ? floorFrom : '',
438	      saveCap ? capFrom : '',
439	      saveTerms ? termsFrom : '',
440	      saveLatePct ? latePctFrom : '',
441	      ...gradeTerms.map(({ grade }) => gradeTermsFrom[grade].trim()),
442	    ].some((from) => from !== '' && !DATE.test(from));
443	    if (badFrom) {
444	      this.settingsError.set('Type a from-date as YYYY-MM-DD, or leave it blank for the sheet\'s today.');
445	      return;
446	    }
447	    if (saveLimit && limit !== '' && !LIMIT.test(limit)) {
448	      this.settingsError.set('Type a clerk limit of 0.00 or more, with up to two decimals, or leave it blank.');
449	      return;
450	    }
451	    if (saveFloor && !LIMIT.test(floor)) {
452	      this.settingsError.set('Type a floor of 0.00 or more, with up to two decimals.');
453	      return;
454	    }
455	    if (saveCap && cap !== '' && !LIMIT.test(cap)) {
456	      this.settingsError.set('Type a cap of 0.00 or more, with up to two decimals, or leave it blank.');
457	      return;
458	    }
459	    if (saveTerms && !TERMS.test(terms)) {
460	      this.settingsError.set('Type terms as a whole number of days, 0 or more.');
461	      return;
462	    }
463	    const badGrade = gradeTerms.find(({ text }) => text !== '' && !TERMS.test(text));
464	    if (badGrade) {
465	      this.settingsError.set(
466	        `Type terms for grade ${badGrade.grade} as a whole number of days, 0 or more, or leave them blank for the sheet's terms.`,
467	      );
468	      return;
469	    }
470	    if (saveLatePct && !LIMIT.test(latePct)) {
471	      this.settingsError.set('Type a late percent of 0.00 or more, with up to two decimals.');
472	      return;
473	    }
474	    if (savePolicyDate && policyDate !== '' && !DATE.test(policyDate)) {
475	      this.settingsError.set('Type a policy date as YYYY-MM-DD, or leave it blank for the sheet\'s today.');
476	      return;
477	    }
478	    if (saveNumberingFrom && numberingFrom !== '' && !DATE.test(numberingFrom)) {
479	      this.settingsError.set('Type a period numbering from date as YYYY-MM-DD, or leave it blank to turn it off.');
480	      return;
481	    }
482	    this.savingSettings = true;
483	    try {
484	      if (saveLimit) {
485	        const settings = await this.service.setClerkLimit(sheet, limit || null, limitFrom || null);
486	        if (this.session.sheetId() !== sheet) return;
487	        if (this.limit().trim() === limit && this.limitFrom().trim() === limitFrom) {
488	          this.limitChanged = false;
489	          this.limitFrom.set('');
490	        }
491	        this.show(settings);
492	      }
493	      if (saveFloor) {
494	        const settings = await this.service.setFloor(sheet, floor, floorFrom || null);
495	        if (this.session.sheetId() !== sheet) return;
496	        if (this.floorInput().trim() === floor && this.floorFrom().trim() === floorFrom) {
497	          this.floorChanged = false;
498	          this.floorFrom.set('');
499	        }
500	        this.show(settings);
501	        this.floorSaved.emit(settings.floors);
502	      }
503	      if (saveCap) {
504	        const settings = await this.service.setCap(sheet, cap || null, capFrom || null);
505	        if (this.session.sheetId() !== sheet) return;
506	        if (this.capInput().trim() === cap && this.capFrom().trim() === capFrom) {
507	          this.capChanged = false;
508	          this.capFrom.set('');
509	        }
510	        this.show(settings);
511	        this.capSaved.emit(settings.caps);
512	      }
513	      if (saveTerms) {
514	        const settings = await this.service.setTerms(sheet, terms, termsFrom || null);
515	        if (this.session.sheetId() !== sheet) return;
516	        if (this.termsInput().trim() === terms && this.termsFrom().trim() === termsFrom) {
517	          this.termsChanged = false;
518	          this.termsFrom.set('');
519	        }
520	        this.show(settings);
521	      }
522	      for (const { grade, text } of gradeTerms) {
523	        const from = gradeTermsFrom[grade].trim();
524	        const settings = await this.service.setGradeTerms(sheet, grade, text || null, from || null);
525	        if (this.session.sheetId() !== sheet) return;
526	        if (this.gradeTermsInput()[grade].trim() === text && this.gradeTermsFrom()[grade].trim() === from) {
527	          this.gradeTermsChanged.delete(grade);
528	          this.setGradeTermsFrom(grade, '');
529	        }
530	        this.show(settings);
531	      }
532	      if (saveLatePct) {
533	        const settings = await this.service.setLatePct(sheet, latePct, latePctFrom || null);
534	        if (this.session.sheetId() !== sheet) return;
535	        if (this.latePctInput().trim() === latePct && this.latePctFrom().trim() === latePctFrom) {
536	          this.latePctChanged = false;
537	          this.latePctFrom.set('');
538	        }
539	        this.show(settings);
540	        this.latePctSaved.emit(settings.latePcts);
541	      }
542	      if (savePolicyDate) {
543	        const settings = await this.service.setPolicyDate(sheet, policyDate || null);
544	        if (this.session.sheetId() !== sheet) return;
545	        if (this.policyDateInput().trim() === policyDate) this.policyDateChanged = false;
546	        this.show(settings);
547	        this.policyDateSaved.emit(settings.policyDate);
548	      }
549	      if (saveNumberingFrom) {
550	        const settings = await this.service.setPeriodNumberingFrom(sheet, numberingFrom || null);
551	        if (this.session.sheetId() !== sheet) return;
552	        if (this.periodNumberingFromInput().trim() === numberingFrom) this.periodNumberingFromChanged = false;
553	        this.show(settings);
554	      }
555	      // Show what is in force in each field, but keep what was typed in one while the save was waiting.
556	      if (!this.limitChanged) this.limit.set(this.clerkLimit() ?? '');
557	      if (!this.floorChanged) this.floorInput.set(this.floor());
558	      if (!this.capChanged) this.capInput.set(this.cap() ?? '');
559	      if (!this.termsChanged) this.termsInput.set(this.terms());
560	      if (!this.latePctChanged) this.latePctInput.set(this.latePct());
561	      this.showGradeTermsInputs();
562	      if (!this.policyDateChanged) this.policyDateInput.set(this.policyDate() ?? '');
563	      if (!this.periodNumberingFromChanged) this.periodNumberingFromInput.set(this.periodNumberingFrom() ?? '');
564	    } catch {
565	      this.settingsError.set('Those settings could not be saved.');
566	    } finally {
567	      this.savingSettings = false;
568	      if (this.settingsResubmit) {
569	        this.settingsResubmit = false;
570	        void this.saveSettings(event);
571	      }
572	    }
573	  }
574	
575	  protected async saveRole(event: Event): Promise<void> {
576	    event.preventDefault();
577	    if (this.savingRole) return;
578	    this.roleError.set(null);
579	    const sheet = this.session.sheetId();
580	    if (!sheet) return;
581	    const user = this.roleUser().trim();
582	    const role = this.role().trim();
583	    if (user === '') {
584	      this.roleError.set('Type a user name.');
585	      return;
586	    }
587	    if (!ROLES.includes(role as Role)) {
588	      this.roleError.set(`Choose a role: ${ROLES.join(' or ')}.`);
589	      return;
590	    }
591	    this.savingRole = true;
592	    try {
593	      const saved = await this.service.setRole(sheet, user, role as Role);
594	      if (this.session.sheetId() !== sheet) return;
595	      this.given.update((list) =>
596	        [...list.filter((r) => r.user !== saved.user), saved].sort((a, b) => a.user.localeCompare(b.user)),
597	      );
598	      this.roleUser.set('');
599	      this.role.set('');
600	    } catch {
601	      this.roleError.set('That role could not be set.');
602	    } finally {
603	      this.savingRole = false;
604	    }
605	  }
606	
607	  private async read(sheet: string): Promise<void> {
608	    try {
609	      const settings = await this.service.get(sheet);
610	      if (this.session.sheetId() === sheet) {
611	        this.show(settings);
612	        if (!this.limitChanged) this.limit.set(settings.clerkLimit ?? '');
613	        if (!this.floorChanged) this.floorInput.set(settings.floor);
614	        if (!this.capChanged) this.capInput.set(settings.cap ?? '');
615	        if (!this.termsChanged) this.termsInput.set(String(settings.terms));
616	        if (!this.latePctChanged) this.latePctInput.set(settings.latePct);
617	        this.showGradeTermsInputs();
618	        if (!this.policyDateChanged) this.policyDateInput.set(settings.policyDate ?? '');
619	        if (!this.periodNumberingFromChanged) this.periodNumberingFromInput.set(settings.periodNumberingFrom ?? '');
620	      }
621	    } catch {
622	      // The settings could not be read; they show as none.
623	    }
624	  }
625	
626	  /** Show each grade's own terms in force in its field, but keep what was typed in one since. */
627	  private showGradeTermsInputs(): void {
628	    this.gradeTermsInput.update((inputs) => {
629	      const next = { ...inputs };
630	      for (const grade of GRADES) if (!this.gradeTermsChanged.has(grade)) next[grade] = this.gradeTermsShown(grade);
631	      return next;
632	    });
633	  }
634	
635	  private show(settings: SheetSettings): void {
636	    this.clerkLimit.set(settings.clerkLimit);
637	    this.floor.set(settings.floor);
638	    this.cap.set(settings.cap);
639	    this.terms.set(String(settings.terms));
640	    this.gradeTerms.set(settings.gradeTerms ?? {});
641	    this.latePct.set(settings.latePct);
642	    this.policyDate.set(settings.policyDate);
643	    this.periodNumberingFrom.set(settings.periodNumberingFrom);
644	    this.given.set(settings.roles);
645	  }
646	}
647	
648	function blankGrades(): Record<Grade, string> {
649	  return { A: '', B: '', C: '' };
